From ff2a94c8631de2970144a07bdc81fbfed36a03a5 Mon Sep 17 00:00:00 2001
From: Mikhail Khachayants <mkhachaiants@gmail.com>
Date: Mon, 30 Dec 2024 23:33:35 +0200
Subject: [PATCH] Fix heap-buffer-overflow error in compileRule and
 _lou_extParseChars

---
 liblouis/compileTranslationTable.c | 3 ++-
 1 file changed, 2 insertions(+), 1 deletion(-)

diff --git a/liblouis/compileTranslationTable.c b/liblouis/compileTranslationTable.c
index 40a56a3..109dcee 100644
--- a/liblouis/compileTranslationTable.c
+++ b/liblouis/compileTranslationTable.c
@@ -1390,7 +1390,8 @@ parseChars(const FileInfo *file, CharsString *result, CharsString *token) {
 		}
 		if (CHARSIZE == 2 && utf32 > 0xffff) {
 			compileError(file, "liblouis has not been compiled for 32-bit Unicode");
-			return 1;
+			result->length = lastOutSize;
+			return 0;
 		}
 		result->chars[out++] = (widechar)utf32;
 	}
